
# Connect to Exchange Online using app credentials (certificate-based or interactive)
# Since we have client_id/secret, we need to connect interactively or with certificate
# For app-only: Connect-ExchangeOnline -AppId ... -CertificateThumbprint ... -Organization ...
# For interactive: Connect-ExchangeOnline

$ErrorActionPreference = "Stop"

# Connect interactively (will open a browser for admin sign-in)
try {
    Connect-ExchangeOnline -Organization flashcargoglobal.onmicrosoft.com -ShowBanner:$false
    Write-Host "Connected to Exchange Online" -ForegroundColor Green
} catch {
    Write-Host "Failed to connect: $_" -ForegroundColor Red
    exit 1
}

