$added = 0
$skipped = 0
foreach ($alias in $newAliases) {
    $smtpAlias = "smtp:$alias"
    $exists = $mailbox.EmailAddresses | Where-Object { $_.ToLower() -eq $smtpAlias.ToLower() }
    if (-not $exists) {
        try {
            Set-Mailbox -Identity "pricing@flashcargoglobal.com" -EmailAddresses @{Add=$smtpAlias}
            Write-Host "  Added: $smtpAlias" -ForegroundColor Green
            $added++
        } catch {
            Write-Host "  Failed to add $smtpAlias : $_" -ForegroundColor Red
        }
    } else {
        $skipped++
    }
}

Write-Host ""
Write-Host "Added: $added | Skipped (already exist): $skipped" -ForegroundColor Cyan

